def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Step 1: Select solution with highest potential improvement
    objectives = np.array([obj for (sol, obj) in archive])
    combined_values = objectives[:, 0] + objectives[:, 1]
    improvement_potential = combined_values / (1 + np.sum(archive[0][0]) * np.mean(weight_lst))
    best_idx = np.argmax(improvement_potential)
    base_solution = archive[best_idx][0].copy()

    new_solution = base_solution.copy()
    n_items = len(weight_lst)
    current_weight = np.sum(weight_lst[new_solution == 1])

    # Step 2: Objective-correlation analysis
    if np.random.rand() < 0.5:
        corr = np.corrcoef(value1_lst, value2_lst)[0, 1]
        for i in range(n_items):
            if np.random.rand() < abs(corr) * 0.8:
                delta_weight = weight_lst[i] * (1 - 2 * new_solution[i])
                if current_weight + delta_weight <= capacity:
                    new_solution[i] = 1 - new_solution[i]
                    current_weight += delta_weight

    # Step 3: Objective-aware swap
    if np.random.rand() < 0.6:
        for i in range(n_items):
            if new_solution[i] == 1 and np.random.rand() < 0.4:
                if current_weight - weight_lst[i] >= 0:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]
                    # Try to add a complementary item
                    candidates = np.where(new_solution == 0)[0]
                    if len(candidates) > 0:
                        j = np.random.choice(candidates)
                        if weight_lst[j] <= capacity - current_weight:
                            new_solution[j] = 1
                            current_weight += weight_lst[j]

    # Step 4: Frontier-guided perturbation
    if len(archive) > 1 and np.random.rand() < 0.4:
        extreme1 = archive[np.argmax(objectives[:, 0])][0]
        extreme2 = archive[np.argmax(objectives[:, 1])][0]
        for i in range(n_items):
            if (extreme1[i] != new_solution[i] or extreme2[i] != new_solution[i]) and np.random.rand() < 0.3:
                if (extreme1[i] == 1 or extreme2[i] == 1) and (weight_lst[i] <= capacity - current_weight):
                    new_solution[i] = 1
                    current_weight += weight_lst[i]

    # Step 5: Adaptive capacity-aware mutation
    remaining_capacity = capacity - current_weight
    if remaining_capacity > 0 and np.random.rand() < 0.7:
        candidates = np.where(new_solution == 0)[0]
        np.random.shuffle(candidates)
        for i in candidates:
            if weight_lst[i] <= remaining_capacity and np.random.rand() < 0.5:
                new_solution[i] = 1
                remaining_capacity -= weight_lst[i]
                if remaining_capacity <= 0:
                    break

    # Step 6: Phase-sensitive mutation
    if np.random.rand() < 0.3:
        if len(archive) < 10:  # Exploration phase
            for i in range(n_items):
                if np.random.rand() < 0.1:
                    if new_solution[i] == 0 and weight_lst[i] <= capacity - current_weight:
                        new_solution[i] = 1
                    elif new_solution[i] == 1:
                        new_solution[i] = 0
        else:  # Exploitation phase
            for i in range(n_items):
                if np.random.rand() < 0.2:
                    if new_solution[i] == 0 and weight_lst[i] <= capacity - current_weight:
                        new_solution[i] = 1

    return new_solution

