def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Step 1: Select the most promising solution based on Pareto optimality and diversity
    objectives = np.array([obj for (sol, obj) in archive])
    pareto_front = []
    for i in range(len(objectives)):
        dominated = False
        for j in range(len(objectives)):
            if i != j and objectives[j][0] >= objectives[i][0] and objectives[j][1] >= objectives[i][1] and (objectives[j][0] > objectives[i][0] or objectives[j][1] > objectives[i][1]):
                dominated = True
                break
        if not dominated:
            pareto_front.append(i)

    if not pareto_front:
        pareto_front = [np.argmax(objectives[:, 0] + objectives[:, 1])]

    best_idx = np.random.choice(pareto_front)
    base_solution = archive[best_idx][0].copy()
    new_solution = base_solution.copy()
    n_items = len(weight_lst)
    current_weight = np.sum(weight_lst[new_solution == 1])

    # Step 2: Value-density guided perturbation
    value_density = (value1_lst + value2_lst) / weight_lst
    sorted_items = np.argsort(-value_density)
    for i in sorted_items:
        if np.random.rand() < 0.7:
            delta_weight = weight_lst[i] * (1 - 2 * new_solution[i])
            if current_weight + delta_weight <= capacity:
                new_solution[i] = 1 - new_solution[i]
                current_weight += delta_weight

    # Step 3: Trade-off aware swap
    if len(archive) > 1:
        other_idx = np.random.choice([i for i in range(len(archive)) if i != best_idx])
        other_solution = archive[other_idx][0]
        for i in range(n_items):
            if other_solution[i] != new_solution[i] and np.random.rand() < 0.5:
                if other_solution[i] == 1 and (current_weight + weight_lst[i] <= capacity):
                    new_solution[i] = 1
                    current_weight += weight_lst[i]
                elif new_solution[i] == 1:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]

    # Step 4: Capacity-constrained mutation
    remaining_capacity = capacity - current_weight
    if remaining_capacity > 0:
        candidates = np.where(new_solution == 0)[0]
        np.random.shuffle(candidates)
        for i in candidates:
            if weight_lst[i] <= remaining_capacity and np.random.rand() < 0.4:
                new_solution[i] = 1
                remaining_capacity -= weight_lst[i]
                if remaining_capacity <= 0:
                    break

    # Step 5: Knee-point focused perturbation
    if np.random.rand() < 0.3:
        knee_point = np.argmin(objectives[:, 0] / (objectives[:, 1] + 1e-6))
        knee_solution = archive[knee_point][0]
        for i in range(n_items):
            if knee_solution[i] != new_solution[i] and np.random.rand() < 0.6:
                if knee_solution[i] == 1 and (current_weight + weight_lst[i] <= capacity):
                    new_solution[i] = 1
                    current_weight += weight_lst[i]
                elif new_solution[i] == 1:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]

    # Step 6: Diversity-enhancing mutation
    if np.random.rand() < 0.2:
        low_contrib_items = np.where((value1_lst + value2_lst) < np.percentile(value1_lst + value2_lst, 25))[0]
        for i in low_contrib_items:
            if np.random.rand() < 0.5:
                if new_solution[i] == 1:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]

    return new_solution

